const USERS = new Map([[1, { id: 1, name: 'Ada' }], [2, { id: 2, name: 'Grace' }]]);

export function getUser(id) {
  return USERS.get(id) ?? null;
}

export function listUsers() {
  return [...USERS.values()];
}

